export function tr(key: Key, vars: Record<string,string|number> = {}) {
  const translationKey = key as TranslationKey;
  const template = key === 'tutorComments' ? tutorCommentOverrides[activeLanguage] : genderedTerminologyOverrides[activeLanguage]?.[activeTeacherSex]?.[key] ?? trackingDocumentOverrides[activeLanguage]?.[key] ?? titleCasingOverrides[activeLanguage]?.[key] ?? helpWorkflowOverrides[activeLanguage]?.[key] ?? roleHelpOverrides[activeLanguage]?.[key] ?? subjectTerminologyOverrides[activeLanguage]?.[key] ?? genderedRoleOverrides[activeLanguage]?.[activeTeacherSex]?.[key] ?? profileSexOverrides[activeLanguage]?.[key] ?? deleteDialogOverrides[activeLanguage]?.[key] ?? electiveOverrides[activeLanguage]?.[key] ?? commonActionOverrides[activeLanguage]?.[key] ?? reportLibraryOverrides[activeLanguage]?.[key] ?? trackingStatusOverrides[activeLanguage]?.[key] ?? teacherSummaryOverrides[activeLanguage]?.[key] ?? dashboardMetricOverrides[activeLanguage]?.[key] ?? centerDataActionOverrides[activeLanguage]?.[key] ?? unifiedConfigurationOverrides[activeLanguage]?.[key] ?? completionOverrides[activeLanguage]?.[key] ?? configurationStatusOverrides[activeLanguage]?.[key] ?? terminologyOverrides[activeLanguage]?.[key] ?? onboardingOverrides[activeLanguage]?.[key] ?? gradeHelpOverrides[activeLanguage]?.[key] ?? focusedOverrides[activeLanguage]?.[key] ?? (activeLanguage === 'es' ? es[translationKey] : translations[activeLanguage][translationKey]);
  let value = Object.entries(vars).reduce((current,[name,replacement]) => current.replaceAll(`{${name}}`,String(replacement)), template);
  // A few workflow/help sentences are shared by languages and contain the
  // role noun inline. Adapt those occurrences as well as standalone labels.
  if (activeTeacherSex === 'FEMALE') {
    if (activeLanguage === 'es') value = value.replace(/\bdel profesor\b/gi, 'de la profesora').replace(/\bdel tutor\b/gi, 'de la tutora').replace(/\bprofesor\/a\b/gi, 'profesora').replace(/\btutor\/a\b/gi, 'tutora').replace(/\bprofesor\b/gi, 'profesora').replace(/\btutor\b/gi, 'tutora');
    if (activeLanguage === 'ca') value = value.replace(/\bdel professor\b/gi, 'de la professora').replace(/\bdel tutor\b/gi, 'de la tutora').replace(/\bprofessor\/a\b/gi, 'professora').replace(/\btutor\/a\b/gi, 'tutora').replace(/\bprofessor\b/gi, 'professora').replace(/\btutor\b/gi, 'tutora');
    if (activeLanguage === 'gl') value = value.replace(/\bdo profesor\b/gi, 'da profesora').replace(/\bdo titor\b/gi, 'da titora').replace(/\bprofesor\/a\b/gi, 'profesora').replace(/\btitor\/a\b/gi, 'titora').replace(/\bprofesor\b/gi, 'profesora').replace(/\btitor\b/gi, 'titora');
  } else {
    value = value.replace(/profesor\/a/gi, 'profesor').replace(/profess(or|ora)\/a/gi, 'professor').replace(/tutor\/a/gi, 'tutor').replace(/titor\/a/gi, 'titor');
  }
  return value;
}

